"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["72842"],{26851(e){e.exports=JSON.parse('{"id":"F334","slug":"replicating-portfolio","name":"Replicating Portfolio (One-Step Binomial)","subject":"Derivatives","section":"Derivatives","topic":"Delta hedging and replication","level":"Intermediate","aliases":["replication","synthetic option","no arbitrage option price","hedge ratio"],"formula":{"latex":"\\\\Delta=\\\\frac{C_{u}-C_{d}}{S(u-d)},\\\\quad B=\\\\frac{C_{u}-\\\\Delta S u}{1+r},\\\\quad C=\\\\Delta S+B","also":[],"text":"Shares held (delta) = (Option value if up - Option value if down) / (Stock price up - Stock price down); Bond holding B = (Option value if up - Delta x Stock price up) / (1 + r); Option value = Delta x S + B"},"symbols":[{"symbol":"C_u, C_d","meaning":"Option value after an up move and a down move","unit":"money"},{"symbol":"S","meaning":"Current stock price","unit":"money"},{"symbol":"u, d","meaning":"Up and down factors for the stock","unit":"number"},{"symbol":"B","meaning":"Cash held, negative if borrowed","unit":"money"},{"symbol":"r","meaning":"Interest rate for the period","unit":"percent"}],"when_to_use":"Use it to price an option by copying it. Hold delta shares and borrow or lend cash so the portfolio pays exactly what the option pays in both outcomes. The portfolio\'s cost today is then the option\'s price, with no probabilities needed.","worked_example":{"problem":"A stock is at 100 and will become 110 or 90 in one period. The interest rate is 5% for the period. What replicates a call with a strike of 100, and what is it worth?","inputs":{"s":100,"u":1.1,"d":0.9,"r":5,"k":100},"steps":[{"label":"Call payoff if up","working":"max(100 x 1.1-100, 0)","value":"10.00"},{"label":"Call payoff if down","working":"max(100 x 0.9-100, 0)","value":"0.00"},{"label":"Shares held = (Cu - Cd) / (S x (u - d))","working":"(10-0) / (100 x (1.1-0.9))","value":"0.5000"},{"label":"Cash holding B = (Cu - delta x S x u) / (1 + r)","working":"(10-0.5 x 100 x 1.1) / (1+0.05)","value":"-42.86"},{"label":"Amount borrowed = -B","working":"--42.8571","value":"42.86"},{"label":"Option value = delta x S + B","working":"0.5 x 100+-42.8571","value":"7.14"},{"label":"Risk-neutral probability = (1 + r - d) / (u - d)","working":"(1+0.05-0.9) / (1.1-0.9)","value":"75.00%"},{"label":"Check: [q x Cu + (1 - q) x Cd] / (1 + r)","working":"(0.75 x 10+(1-0.75) x 0) / (1+0.05)","value":"7.14"}],"answer":"The option pays 10.00 if the stock rises and 0.00 if it falls. Holding 0.5000 shares and borrowing 42.86 copies those payoffs, so the option is worth 7.14. The risk-neutral check gives the same value."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Stock price","unit":"money","type":"number","default":100,"hint":""},{"id":"u","label":"Up factor","unit":"","type":"number","default":1.1,"hint":""},{"id":"d","label":"Down factor","unit":"","type":"number","default":0.9,"hint":""},{"id":"r","label":"Interest rate per period","unit":"%","type":"number","default":5,"hint":""},{"id":"k","label":"Strike price","unit":"money","type":"number","default":100,"hint":""}],"checks":[{"expr":"u>1+r and d<1+r and d>0","message":"The up factor must exceed 1 + r, and the down factor must be below 1 + r and above zero."}],"steps":[{"id":"cu","label":"Call payoff if up","expr":"max(s*u-k, 0)","format":"money"},{"id":"cd","label":"Call payoff if down","expr":"max(s*d-k, 0)","format":"money"},{"id":"delta","label":"Shares held = (Cu - Cd) / (S x (u - d))","expr":"(cu-cd)/(s*(u-d))","format":"num4"},{"id":"b","label":"Cash holding B = (Cu - delta x S x u) / (1 + r)","expr":"(cu-delta*s*u)/(1+r)","format":"money"},{"id":"borrow","label":"Amount borrowed = -B","expr":"-b","format":"money"},{"id":"price","label":"Option value = delta x S + B","expr":"delta*s+b","format":"money"},{"id":"qq","label":"Risk-neutral probability = (1 + r - d) / (u - d)","expr":"(1+r-d)/(u-d)","format":"pct2"},{"id":"check","label":"Check: [q x Cu + (1 - q) x Cd] / (1 + r)","expr":"(qq*cu+(1-qq)*cd)/(1+r)","format":"money"}],"results":["delta","price"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"delta":0.5,"b":-42.857142857142854,"price":7.142857142857146,"check":7.142857142857142}},"finder":{"finds":"A portfolio that copies an option, and its value","needs":"Stock, up and down factors, rate, strike"},"related":[{"slug":"binomial-option-two-step","name":"Binomial Option Pricing (Two Steps)"},{"slug":"delta-hedge-shares","name":"Delta Hedge and Hedging Error"}],"related_ids":["F330","F333"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi mathvariant=\\"normal\\">\u0394</mi><mo>=</mo><mfrac><mrow><msub><mi>C</mi><mi>u</mi></msub><mo>\u2212</mo><msub><mi>C</mi><mi>d</mi></msub></mrow><mrow><mi>S</mi><mo stretchy=\\"false\\">(</mo><mi>u</mi><mo>\u2212</mo><mi>d</mi><mo stretchy=\\"false\\">)</mo></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>B</mi><mo>=</mo><mfrac><mrow><msub><mi>C</mi><mi>u</mi></msub><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>S</mi><mi>u</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>C</mi><mo>=</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>S</mi><mo>+</mo><mi>B</mi></mrow><annotation encoding=\\"application/x-tex\\">\\\\Delta=\\\\frac{C_{u}-C_{d}}{S(u-d)},\\\\quad B=\\\\frac{C_{u}-\\\\Delta S u}{1+r},\\\\quad C=\\\\Delta S+B</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"rent-vs-buy-user-cost","name":"Rent vs Buy: Annual Cost of Owning"},"next":{"slug":"repo-interest","name":"Repo: Interest, Haircut and Repurchase Price"},"lesson":null,"total":522}')}}]);